# 请在下面写出 Cat 类和 let_animal_speak 函数

answer:
class Animal:
    def speak(self):
        print("...")

class Dog(Animal):
    def speak(self):
        print("Woof!")

class Cat(Animal):
    def speak(self):
        print("Meow!")

def let_animal_speak(animal):
    animal.speak()

let_animal_speak(Dog())
let_animal_speak(Cat())
